// ?fill@TaintBuffer@@QAEXE@Z
// partial score=0.98 date=2026-09-11
// cl: /DNDEBUG /MD
// Retail 0x00726EA0: fill the taint overlay's dword and byte buffers.
//
// TaintBuffer is the descriptive name established by the adjacent constructor,
// init, surface-fill, reacquire, and dirty-cell methods.  The target gates on
// TheWritableGlobalData->m_taintOn and clamps the requested alpha to the
// TaintAlpha field before broadcasting it to the two cell buffers.

class GlobalData
{
public:
	unsigned char m_pad00[0xCA0];
	unsigned char m_taintAlpha;
	unsigned char m_padCA1[0xCF5 - 0xCA1];
	unsigned char m_taintOn;
};

extern GlobalData *TheWritableGlobalData;

class TaintBuffer
{
public:
	void fill(unsigned char alpha);

private:
	unsigned int m_width;
	unsigned int m_height;
	unsigned char m_pad08[0x18 - 0x08];
	unsigned int *m_dwords;
	unsigned char m_pad1C[0x38 - 0x1C];
	unsigned char *m_bytes;
};

// ?fill@TaintBuffer@@QAEXE@Z
void TaintBuffer::fill(unsigned char alpha)
{
	GlobalData *g = TheWritableGlobalData;
	if (!g)
		return;
	if (!g->m_taintOn)
		return;

	unsigned char floor = g->m_taintAlpha;
	if (alpha < floor)
		alpha = floor;

	unsigned int color = alpha;
	color = (color << 8) | alpha;
	color = (color << 8) | alpha;
	color = (color << 8) | alpha;

	unsigned int *dst = m_dwords;
	unsigned int y;
	for (y = 0; y < m_height; y++)
	{
		unsigned int x;
		for (x = 0; x < m_width; )
		{
			*dst = color;
			x++;
			dst++;
		}
	}

	unsigned char *row = m_bytes;
	for (y = 0; y < m_height; y++, row += m_width)
	{
		unsigned int i;
		for (i = 0; i < m_width; )
		{
			row[i] = alpha;
			i++;
		}
	}
}
